import fs from 'node:fs';
import { projectHeader, projectHeaderStylesheet } from './project-header.mjs';

// The other two landing pages are generated by render-vr.mjs and render-masb.mjs.
const pages = [
  { file: 'dist/projects/index.html', base: '../', current: true, legacy: /\s*<header class="site-header">[\s\S]*?<\/header>/ },
  { file: 'dist/projects/world-sensing-music-station/index.html', base: '../../', placement: 'overlay', legacy: /<header class="station-header">[\s\S]*?<\/header>/ },
  { file: 'dist/projects/polaroid-of-yesterday/index.html', base: '../../', placement: 'room', legacy: /\s*<nav class="room-breadcrumb"[\s\S]*?<\/nav>/ },
];
for (const page of pages) {
  let html = fs.readFileSync(page.file, 'utf8');
  const header = projectHeader(page);
  if (html.includes('data-project-header')) html = html.replace(/<header class="project-header\b[\s\S]*?<\/header>/, header);
  else if (page.current) {
    html = html.replace(page.legacy, '');
    html = html.replace('<body>', `<body>\n  ${header}`);
  } else if (page.placement === 'room') {
    html = html.replace(page.legacy, '');
    html = html.replace('<body>', `<body>\n  ${header}`);
  } else html = html.replace(page.legacy, header);
  if (html.includes('project-header.css')) html = html.replace(/<link rel="stylesheet" href="[^"]*project-header\.css[^"]*">/, projectHeaderStylesheet(page.base));
  else html = html.replace('</head>', `  ${projectHeaderStylesheet(page.base)}\n</head>`);
  fs.writeFileSync(page.file, html);
}
console.log('Rendered shared navigation for Projects, Music Station and Polaroid.');
